    [10772]={name="Glutton's Cleaver",quality=3,ilvl=42,reqLevel=37,sourceType="boss_drop",instructions="Drops from Glutton.",zone="Razorfen Downs",npc="Glutton",proc="Chance on hit: Wounds the target causing them to bleed for 70 damage over 7 sec."},
