    [10805]={name="Eater of the Dead",quality=3,ilvl=54,reqLevel=49,sourceType="boss_drop",instructions="Drops from Ogom the Wretched.",zone="Sunken Temple",npc="Ogom the Wretched",proc="Chance on hit: Steals 21 life from the target enemy. Deals 3 times as much damage to Undead."},
    [10821]={name="Sower's Cloak",quality=2,ilvl=15,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Mura Runetotem'. Pick it over the other reward choices. Starts with Tonga Runetotem in Silverpine Forest. Objective: Speak with Mura Runetotem in the Sepulcher.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
    [10823]={name="Vanquisher's Sword",quality=3,ilvl=44,reqLevel=39,sourceType="quest_reward",instructions="Reward from the quest 'Bring the Light'.",zone="Razorfen Downs",questName="Bring the Light",lore="In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious..."},
    [10837]={name="Tooth of Eranikus",quality=3,ilvl=56,reqLevel=51,sourceType="boss_drop",instructions="Drops from Shade of Eranikus.",zone="Sunken Temple",npc="Shade of Eranikus",lore="What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself.",proc="Equip: Improves your chance to hit by 1.0%."},
    [10838]={name="Might of Hakkar",quality=3,ilvl=54,reqLevel=49,sourceType="boss_drop",instructions="Drops from Avatar of Hakkar.",zone="Sunken Temple",npc="Avatar of Hakkar",proc="Equip: Improves your chance to hit by 0.5%."},
    [10847]={name="Dragon's Call",quality=4,ilvl=57,reqLevel=52,sourceType="boss_drop",instructions="Drops from Shade of Eranikus.",zone="Sunken Temple",npc="Shade of Eranikus",lore="What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself.",proc="Chance on hit: Calls forth an Emerald Dragon Whelp to protect you in battle for a short period of time."},
    [11086]={name="Jang'thraze the Protector",quality=3,ilvl=50,reqLevel=45,sourceType="boss_drop",instructions="Drops from Chief Ukorz Sandscalp.",zone="Zul'Farrak",npc="Chief Ukorz Sandscalp",proc="Use: Combines Jang'thraze and Sang'thraze to form the mighty sword, Sul'thraze."},
    [11120]={name="Belgrom's Hammer",quality=2,ilvl=55,reqLevel=44,sourceType="quest_reward",instructions="Reward from the quest 'Betrayed'. Pick it over the other reward choices. Starts with Ag'tor Bloodfist in Orgrimmar. Objective: Speak to Belgrom Rockmaul in Orgrimmar.",zone="Orgrimmar",questName="Betrayed",lore="Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly. Ah, this is indeed a good day. Thank you for your help."},
    [11121]={name="Darkwater Talwar",quality=3,ilvl=27,reqLevel=22,sourceType="boss_drop",instructions="Drops from Lady Sarevess.",zone="Blackfathom Deeps",npc="Lady Sarevess",proc="Chance on hit: Sends a shadowy bolt at the enemy causing 28 Shadow damage."},
    [11193]={name="Blazewind Breastplate",quality=2,ilvl=57,reqLevel=40,sourceType="quest_reward",instructions="Reward from the quest 'Tremors of the Earth'. Pick it over the other reward choices. Starts with Garek in Badlands. Objective: Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.Place the runestones in the Seal of the Earth to free Blacklash and Hematus.Slay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.",zone="Badlands",questName="Tremors of the Earth",lore="It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor."},
    [11303]={name="Fine Shortbow",quality=2,ilvl=16,reqLevel=11,sourceType="vendor",instructions="Bought from Rallic Finn in Stormwind (Alliance) or Abigail Sawyer in Undercity (Horde).",zone="Undercity",npc="Abigail Sawyer"},
