    [11675]={name="Shadefiend Boots",quality=3,ilvl=55,reqLevel=50,sourceType="boss_drop",instructions="Drops from Anub'shiah.",zone="Blackrock Depths",npc="Anub'shiah"},
    [11684]={name="Ironfoe",quality=4,ilvl=60,reqLevel=55,sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay.",proc="Equip: Attacks have a chance to grant 2 extra attacks on your next swing. Attacks against Orcs are 2 times as likely to activate this effect. (Proc chance: 6%, 100ms cooldown)"},
