    [11744]={name="Bloodfist",quality=3,ilvl=56,reqLevel=51,sourceType="boss_drop",instructions="Drops from Phalanx.",zone="Blackrock Depths",npc="Phalanx",proc="Chance on hit: Wounds the target for 35 damage."},
